export type ParsedOpenFreeInstruction<
  TProgram extends string = typeof ANTE_UP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    market: TAccountMetas[0];
    admission: TAccountMetas[1];
    walletStats: TAccountMetas[2];
    walletMarket: TAccountMetas[3];
    record: TAccountMetas[4];
    owner: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: OpenFreeInstructionData;
};

export function parseOpenFreeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenFreeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      market: getNextAccount(),
      admission: getNextAccount(),
      walletStats: getNextAccount(),
      walletMarket: getNextAccount(),
      record: getNextAccount(),
      owner: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getOpenFreeInstructionDataDecoder().decode(instruction.data),
  };
}
